# -*- coding: utf-8 -*-
from entries1 import E
G='purete'
E('10',G,"En entrant aux toilettes","[Au nom d'Allah.] Ô Allah, je me réfugie auprès de Toi contre les démons mâles et femelles (ou : contre le mal et ceux qui le font).")
E('11',G,"En sortant des toilettes","(Je demande) Ton pardon.")
E('12',G,"Avant les ablutions","Au nom d'Allah.")
E('13',G,"Après les ablutions : la double attestation","Je témoigne qu'il n'y a de divinité digne d'adoration qu'Allah, Seul, sans associé, et je témoigne que Muhammad est Son serviteur et Son messager.",
  b="Les huit portes du Paradis lui sont ouvertes ; il entre par celle qu'il veut (Muslim).")
E('14',G,"Après les ablutions : « fais-moi parmi ceux qui se repentent »","Ô Allah, fais-moi parmi ceux qui se repentent sans cesse et parmi ceux qui se purifient.")
E('15',G,"Après les ablutions : « Gloire à Toi, ô Allah »","Gloire à Toi, ô Allah, et louange à Toi. Je témoigne qu'il n'y a de divinité digne d'adoration que Toi ; je Te demande pardon et je me repens à Toi.")

G='maison'
E('5',G,"En s'habillant","Louange à Allah qui m'a vêtu de ce (vêtement) et me l'a accordé sans force ni pouvoir de ma part.")
E('6',G,"En portant un vêtement neuf","Ô Allah, à Toi la louange, c'est Toi qui m'en as vêtu. Je Te demande son bien et le bien de ce pour quoi il a été fait, et je me réfugie auprès de Toi contre son mal et le mal de ce pour quoi il a été fait.")
E('7',G,"À quelqu'un qui porte un vêtement neuf (1)","Use-le, et qu'Allah te le remplace (par un autre).")
E('8',G,"À quelqu'un qui porte un vêtement neuf (2)","Porte du neuf, vis digne de louange et meurs en martyr.")
E('9',G,"En se déshabillant","Au nom d'Allah.")
E('16',G,"En sortant de chez soi","Au nom d'Allah ; je place ma confiance en Allah ; il n'y a de force ni de puissance qu'en Allah.",
  b="Il lui est dit : tu es guidé, suffi et protégé, et le Diable s'écarte de lui.")
E('17',G,"En sortant : se protéger de l'égarement et de l'injustice","Ô Allah, je me réfugie auprès de Toi contre le fait d'égarer ou d'être égaré, de faire trébucher ou de trébucher, d'être injuste ou de subir l'injustice, d'agir en ignorant ou de subir l'ignorance d'autrui.")
E('18',G,"En entrant chez soi","Au nom d'Allah nous entrons, au nom d'Allah nous sortons, et sur notre Seigneur nous nous appuyons. (Puis saluer les gens de la maison.)")

G='mosquee'
E('19',G,"En allant à la mosquée : l'invocation de la lumière","Ô Allah, mets une lumière dans mon cœur, une lumière sur ma langue, une lumière dans mon ouïe, une lumière dans ma vue, une lumière au-dessus de moi, une lumière au-dessous de moi, une lumière à ma droite, une lumière à ma gauche, une lumière devant moi et une lumière derrière moi. Mets une lumière dans mon âme, rends grande pour moi la lumière, amplifie pour moi la lumière, donne-moi une lumière et fais de moi une lumière. Ô Allah, accorde-moi une lumière, et mets une lumière dans mes nerfs, ma chair, mon sang, mes cheveux et ma peau.",
  v=[('bukhari',6316),('muslim',763)])
E('20',G,"En entrant à la mosquée","Je me réfugie auprès d'Allah l'Immense, auprès de Son noble Visage et de Son pouvoir éternel, contre le Diable banni. [Au nom d'Allah, et que la prière et le salut soient sur le Messager d'Allah.] Ô Allah, ouvre-moi les portes de Ta miséricorde.",
  note="Entrer du pied droit.")
E('21',G,"En sortant de la mosquée","Au nom d'Allah, et que la prière et le salut soient sur le Messager d'Allah. Ô Allah, je Te demande de Ta grâce. Ô Allah, protège-moi du Diable banni.",note="Sortir du pied gauche.")
E('22',G,"En entendant l'appel à la prière","Répéter ce que dit le muezzin, sauf à « Venez à la prière » et « Venez au succès », où l'on dit : il n'y a de force ni de puissance qu'en Allah.",
  ar="لا حَـوْلَ وَلا قُـوَّةَ إِلاّ بِالله",tr="Lā ḥawla wa lā quwwata illā billāh")
E('23',G,"Après les attestations du muezzin","Je témoigne aussi qu'il n'y a de divinité digne d'adoration qu'Allah, Seul, sans associé, et que Muhammad est Son serviteur et Son messager. Je suis satisfait d'Allah comme Seigneur, de Muhammad comme messager et de l'Islam comme religion.",
  b="Ses péchés lui sont pardonnés (Muslim).")
E('25',G,"Après l'appel à la prière","Ô Allah, Seigneur de cet appel parfait et de la prière qui va être accomplie, accorde à Muhammad le moyen d'accès (al-wasîla) et l'excellence, et ressuscite-le au rang digne de louange que Tu lui as promis. [Tu ne manques pas à Ta promesse.]",
  b="Il obtient l'intercession du Prophète ﷺ au Jour de la Résurrection (Al-Bukhari).",note="Prier d'abord sur le Prophète ﷺ ; et l'invocation entre l'appel et l'iqama n'est pas rejetée.")

G='priere'
E('27',G,"Ouverture de la prière : « éloigne-moi de mes péchés »","Ô Allah, éloigne-moi de mes péchés comme Tu as éloigné l'Orient de l'Occident. Ô Allah, purifie-moi de mes péchés comme on purifie le vêtement blanc de la saleté. Ô Allah, lave-moi de mes péchés par la neige, l'eau et la grêle.")
E('28',G,"Ouverture de la prière : « Subhânaka Allâhumma »","Gloire à Toi, ô Allah, et louange à Toi. Béni soit Ton nom, élevée soit Ta majesté, et il n'y a de divinité digne d'adoration que Toi.")
E('29',G,"Ouverture de la prière : « J'ai tourné mon visage »","J'ai tourné mon visage, en monothéiste sincère, vers Celui qui a créé les cieux et la terre, et je ne suis pas du nombre des polythéistes. Ma prière, mes sacrifices, ma vie et ma mort appartiennent à Allah, Seigneur des mondes, sans associé ; c'est ce qui m'a été ordonné, et je suis du nombre des musulmans. Ô Allah, Tu es le Roi, il n'y a de divinité que Toi. Tu es mon Seigneur et je suis Ton serviteur. J'ai été injuste envers moi-même et j'ai reconnu mon péché : pardonne-moi tous mes péchés, car nul ne pardonne les péchés que Toi. Guide-moi vers le meilleur des comportements, nul n'y guide que Toi, et détourne de moi le mauvais comportement, nul ne l'écarte que Toi. Me voici à Ton service et à Ton obéissance ; tout le bien est entre Tes mains, et le mal ne Te revient pas. Je suis par Toi et vers Toi. Béni et exalté sois-Tu ; je Te demande pardon et je me repens à Toi.")
E('33',G,"Inclinaison : Subhâna rabbiyal-'Azîm (3 fois)","Gloire à mon Seigneur, l'Immense.",c=3)
E('34',G,"Inclinaison et prosternation : « Subhânaka Allâhumma rabbanâ »","Gloire à Toi, ô Allah, notre Seigneur, et louange à Toi. Ô Allah, pardonne-moi.")
E('35',G,"Inclinaison et prosternation : « Subbûhun quddûs »","Infiniment glorifié, infiniment saint, Seigneur des anges et de l'Esprit (Jibrîl).")
E('37',G,"Inclinaison et prosternation : « Subhâna dhil-jabarût »","Gloire au Détenteur de la toute-puissance, de la royauté, de la grandeur et de la majesté.")
E('38',G,"En se relevant de l'inclinaison","Allah entend celui qui Le loue.")
E('39',G,"Une fois redressé : « Rabbanâ wa lakal-hamd »","Notre Seigneur, à Toi la louange, une louange abondante, bonne et bénie.")
E('40',G,"Une fois redressé : « emplissant les cieux et la terre »","(Une louange) qui emplit les cieux, la terre, ce qui est entre eux et ce que Tu voudras au-delà. Ô Toi digne de louange et de gloire, c'est la parole la plus juste qu'ait dite le serviteur, et nous sommes tous Tes serviteurs : ô Allah, nul ne peut retenir ce que Tu donnes, nul ne peut donner ce que Tu retiens, et la fortune du fortuné ne lui sert à rien contre Toi.")
E('41',G,"Prosternation : Subhâna rabbiyal-A'lâ (3 fois)","Gloire à mon Seigneur, le Très-Haut.",c=3)
E('44',G,"Prosternation : « À Toi je me prosterne »","Ô Allah, c'est devant Toi que je me prosterne, en Toi que je crois, à Toi que je me soumets. Mon visage se prosterne devant Celui qui l'a créé, lui a donné forme et a ouvert son ouïe et sa vue. Béni soit Allah, le meilleur des créateurs.")
E('46',G,"Prosternation : « pardonne-moi tous mes péchés »","Ô Allah, pardonne-moi tous mes péchés, les petits et les grands, les premiers et les derniers, ceux commis ouvertement et ceux commis en secret.")
E('47',G,"Prosternation : « je me réfugie dans Ton agrément »","Ô Allah, je me réfugie dans Ton agrément contre Ta colère, dans Ton pardon contre Ton châtiment, et je me réfugie en Toi contre Toi. Je ne saurais dénombrer Tes louanges : Tu es tel que Tu T'es Toi-même loué.")
E('48',G,"Entre les deux prosternations (1)","Seigneur, pardonne-moi. Seigneur, pardonne-moi.")
E('49',G,"Entre les deux prosternations (2)","Ô Allah, pardonne-moi, fais-moi miséricorde, guide-moi, redresse-moi, accorde-moi le bien-être, accorde-moi ma subsistance et élève-moi.")
E('52',G,"Le Tashahhud","Les salutations sont à Allah, ainsi que les prières et les bonnes choses. Que la paix soit sur toi, ô Prophète, ainsi que la miséricorde d'Allah et Ses bénédictions. Que la paix soit sur nous et sur les serviteurs vertueux d'Allah. Je témoigne qu'il n'y a de divinité digne d'adoration qu'Allah, et je témoigne que Muhammad est Son serviteur et Son messager.")
E('53',G,"La prière sur le Prophète ﷺ (as-salât al-ibrâhîmiyya)","Ô Allah, prie sur Muhammad et sur la famille de Muhammad, comme Tu as prié sur Ibrahim et sur la famille d'Ibrahim ; Tu es certes digne de louange et de gloire. Ô Allah, bénis Muhammad et la famille de Muhammad, comme Tu as béni Ibrahim et la famille d'Ibrahim ; Tu es certes digne de louange et de gloire.")
E('55',G,"Avant le salâm : contre les quatre épreuves","Ô Allah, je me réfugie auprès de Toi contre le châtiment de la tombe, contre le châtiment de l'Enfer, contre l'épreuve de la vie et de la mort, et contre le mal de l'épreuve du faux Messie (Ad-Dajjâl).")
E('56',G,"Avant le salâm : contre le péché et la dette","Ô Allah, je me réfugie auprès de Toi contre le châtiment de la tombe ; je me réfugie auprès de Toi contre l'épreuve du faux Messie ; je me réfugie auprès de Toi contre l'épreuve de la vie et de la mort. Ô Allah, je me réfugie auprès de Toi contre le péché et la dette.")
E('57',G,"Avant le salâm : l'invocation enseignée à Abu Bakr","Ô Allah, j'ai été très injuste envers moi-même et nul ne pardonne les péchés que Toi : accorde-moi un pardon venant de Toi et fais-moi miséricorde, Tu es certes le Pardonneur, le Très Miséricordieux.")
E('58',G,"Avant le salâm : « pardonne-moi ce que j'ai avancé et retardé »","Ô Allah, pardonne-moi ce que j'ai fait avant et ce que je ferai après, ce que j'ai caché et ce que j'ai montré, mes excès, et ce que Tu connais mieux que moi. Tu es Celui qui avance et Celui qui retarde ; il n'y a de divinité digne d'adoration que Toi.")
E('59',G,"« Aide-moi à T'invoquer, à Te remercier »","Ô Allah, aide-moi à T'invoquer, à Te remercier et à bien T'adorer.",note="Le Prophète ﷺ a recommandé à Mu'adh de ne pas la délaisser à la fin de chaque prière.")
E('60',G,"Avant le salâm : contre l'avarice et la lâcheté","Ô Allah, je me réfugie auprès de Toi contre l'avarice, je me réfugie auprès de Toi contre la lâcheté, je me réfugie auprès de Toi contre le fait d'être ramené à l'âge le plus vil, et je me réfugie auprès de Toi contre l'épreuve de ce monde et le châtiment de la tombe.")
E('61',G,"Demander le Paradis","Ô Allah, je Te demande le Paradis et je me réfugie auprès de Toi contre le Feu.")
